// Diário (redesign): boletins with a note written by the user, newest first, one compact row each.
// Notes generated by the screenshot import ("Importado do betclic") are not journal entries.
import React, { useMemo } from 'react';
import { FlatList, StyleSheet, View } from 'react-native';
import { Stack, useRouter } from 'expo-router';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { BoletinStatus, type BoletinDetail } from '@betintel/shared';
import { AppText } from '../../components/ui/AppText';
import { EmptyState } from '../../components/ui/EmptyState';
import { ListCard, ListRow } from '../../components/ui/ListCard';
import { StatusPill } from '../../components/ui/StatusPill';
import { Appear } from '../../components/ui/Appear';
import { TeamBadge } from '../../components/ui/TeamBadge';
import { useBoletins } from '../../services/boletinService';
import { useTheme } from '../../theme/useTheme';
import { formatCurrency, formatOdds } from '../../utils/formatters';

const AUTO_NOTE = /^importado d[oa] /i;

function titleOf(b: BoletinDetail): string {
  if (b.name) return b.name;
  const first = b.items[0];
  if (b.items.length === 1 && first) return `${first.homeTeam} vs ${first.awayTeam}`;
  return `Múltipla · ${b.items.length} seleções`;
}

export default function JournalScreen() {
  const insets = useSafeAreaInsets();
  const router = useRouter();
  const { colors } = useTheme();
  const boletinsQuery = useBoletins();

  const entries = useMemo(
    () =>
      (boletinsQuery.data ?? [])
        .filter((b) => b.notes && b.notes.trim().length > 0 && !AUTO_NOTE.test(b.notes.trim()))
        .sort((a, b) => new Date(b.betDate ?? b.createdAt).getTime() - new Date(a.betDate ?? a.createdAt).getTime()),
    [boletinsQuery.data],
  );

  const renderItem = ({ item, index }: { item: BoletinDetail; index: number }) => {
    const stake = Number(item.stake);
    const profit = Number(item.actualReturn ?? 0) - (item.isFreebet ? 0 : stake);
    const pending = item.status === BoletinStatus.PENDING;
    const date = new Date(item.betDate ?? item.createdAt).toLocaleDateString('pt-PT', { day: '2-digit', month: 'short', year: 'numeric' });
    return (
      <Appear index={index}>
      <ListCard>
        <ListRow accessibilityLabel={titleOf(item)} onPress={() => router.push(`/boletins/${item.id}`)} style={styles.row}>
          <View style={styles.top}>
            {item.items[0] ? <TeamBadge name={item.items[0].homeTeam} size={32} variant={item.items[0].sport === 'TENNIS' ? 'player' : 'auto'} /> : null}
            <View style={styles.flex}>
              <AppText numberOfLines={1} variant="bodyStrong">{titleOf(item)}</AppText>
              <AppText variant="caption">{date} · {formatCurrency(stake)} · @{formatOdds(item.totalOdds)}</AppText>
            </View>
            <View style={styles.right}>
              {!pending ? (
                <AppText tone={profit > 0 ? 'positive' : profit < 0 ? 'negative' : 'secondary'} variant="number">
                  {profit > 0 ? '+' : profit < 0 ? '−' : ''}{formatCurrency(Math.abs(profit))}
                </AppText>
              ) : null}
              <StatusPill compact status={item.status} />
            </View>
          </View>
          <AppText numberOfLines={4} style={[styles.note, { backgroundColor: colors.surfaceRaised, borderLeftWidth: 0 }]} variant="body">
            {item.notes}
          </AppText>
        </ListRow>
      </ListCard>
      </Appear>
    );
  };

  return (
    <View style={[styles.screen, { backgroundColor: colors.background }]}>
      <Stack.Screen
        options={{
          title: 'Diário',
          headerShown: true,
          headerShadowVisible: false,
          headerStyle: { backgroundColor: colors.background },
          headerTintColor: colors.textPrimary,
        }}
      />
      <FlatList
        contentContainerStyle={{ gap: 12, paddingBottom: insets.bottom + 48, paddingHorizontal: 20, paddingTop: 8 }}
        data={entries}
        keyExtractor={(item) => item.id}
        ListEmptyComponent={
          boletinsQuery.isLoading ? null : (
            <EmptyState
              icon="notebook-outline"
              message="Escreve uma nota num boletim (porque apostaste, o que correu bem ou mal) e ela aparece aqui."
              title="Ainda sem notas"
            />
          )
        }
        renderItem={renderItem}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1 },
  row: { alignItems: 'stretch', flexDirection: 'column', gap: 10 },
  top: { alignItems: 'flex-start', flexDirection: 'row', gap: 12 },
  flex: { flex: 1, gap: 2 },
  right: { alignItems: 'flex-end', gap: 4 },
  note: { borderRadius: 12, overflow: 'hidden', paddingHorizontal: 12, paddingVertical: 10 },
});
